function accept_fix(fix_case, ask) {
  const jobs = fix_case.jobs;
  const repaired = jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const repairedJobs = jobs.filter(j => j.before === 'fail' && j.after === 'pass').map(j => j.name);

  const tokenize = text => (text.toLowerCase().match(/[a-z0-9]+/g) || []);
  const repairedTokens = repairedJobs.map(name => new Set(tokenize(name)));

  function isExactJob(nearby) {
    const match = nearby.situation.match(/job\s+["']([^"']+)["']/);
    if (!match) return false;
    const afterQuote = nearby.situation.slice(nearby.situation.indexOf(match[0]) + match[0].length);
    return !/but/i.test(afterQuote);
  }

  const candidates = fix_case.nearby.filter(n => n.before !== n.after && !isExactJob(n));
  if (candidates.length === 0) return true;

  function score(nearby) {
    const tokens = new Set(tokenize(nearby.situation));
    let maxScore = 0;
    for (const jobTokens of repairedTokens) {
      let intersection = 0;
      for (const t of tokens) if (jobTokens.has(t)) intersection++;
      const union = tokens.size + jobTokens.size - intersection;
      const jaccard = intersection / union;
      if (jaccard > maxScore) maxScore = jaccard;
    }
    return maxScore;
  }

  candidates.sort((a, b) => {
    const diff = score(b) - score(a);
    if (diff !== 0) return diff;
    return a.situation.length - b.situation.length;
  });

  const asks = Math.min(3, candidates.length);
  for (let i = 0; i < asks; i++) {
    const truth = ask(candidates[i].id);
    if (truth === null) break;
    if (truth === candidates[i].before) {
      return false;
    }
  }

  return true;
}

function accept_fix(fix_case, ask) {
  const jobs = fix_case.jobs;
  const repaired = jobs.some(j => j.before === 'fail' && j.after === 'pass');
  const lost = jobs.some(j => j.before === 'pass' && j.after === 'fail');
  if (!repaired || lost) return false;

  const jobNames = new Set(jobs.map(j => j.name));

  function isCoveredExactJob(n) {
    const m = n.situation.match(/job\s+["']([^"']+)["']/);
    if (!m) return false;
    const name = m[1];
    if (!jobNames.has(name)) return false;
    const after = n.situation.slice(n.situation.indexOf(m[0]) + m[0].length);
    return !/but/i.test(after);
  }

  function keyText(n) {
    const m = n.situation.match(/job\s+["']([^"']+)["']/);
    return m ? m[1] : n.situation;
  }

  const candidates = fix_case.nearby.filter(n => n.before !== n.after && !isCoveredExactJob(n));
  if (candidates.length === 0) return true;

  const tokenize = text => (text.toLowerCase().match(/[a-z0-9]+/g) || []);

  let correctJobs = jobs.filter(j => j.before === 'pass');
  if (correctJobs.length === 0) {
    correctJobs = jobs.filter(j => j.after === 'pass');
  }
  if (correctJobs.length === 0) {
    correctJobs = jobs;
  }
  const correctTokens = correctJobs.map(j => new Set(tokenize(j.name)));

  function score(n) {
    const tokens = new Set(tokenize(keyText(n)));
    let max = 0;
    for (const jobTokens of correctTokens) {
      let inter = 0;
      for (const t of tokens) if (jobTokens.has(t)) inter++;
      const union = tokens.size + jobTokens.size - inter;
      const jaccard = inter / union;
      if (jaccard > max) max = jaccard;
    }
    return max;
  }

  const sorted = candidates.slice().sort((a, b) => {
    const diff = score(b) - score(a);
    if (diff !== 0) return diff;
    return a.situation.length - b.situation.length;
  });

  const picked = [];
  const seenKeys = new Set();
  for (const n of sorted) {
    const key = keyText(n);
    if (seenKeys.has(key)) continue;
    seenKeys.add(key);
    picked.push(n);
    if (picked.length === 3) break;
  }
  if (picked.length < 3) {
    const pickedSet = new Set(picked);
    for (const n of sorted) {
      if (!pickedSet.has(n)) {
        picked.push(n);
        if (picked.length === 3) break;
      }
    }
  }

  for (const n of picked) {
    const truth = ask(n.id);
    if (truth === null) break;
    if (truth === n.before) return false;
  }

  return true;
}

